//! Two native parent rounds and independently admitted funded branches. Every
//! model protocol/profile is synthetic; no real provider/Spotify/system effect.
use super::*;
use crate::pet_runtime::{criteria::NATIVE_MESSAGE_CRITERION,disclosure_consent::Consent,native_peer_plan};
struct Env{base:IterationEnv,waits:AtomicUsize,service:bool,revoke:bool,denied:AtomicBool}
impl Env{
 fn service(&self){
  let s=&self.base.s;let inbox=s.a.message_inbox("integration_spotify",None,8,crate::assistant_memory::now()).unwrap();let r=&inbox.items.iter().find(|i|i.receipt.envelope().schema_version==12).unwrap().receipt;
  let mut reviewed=data_review(s,r,"own-derived-service-goal").unwrap().approve(crate::assistant_memory::now(),Arc::new(||true)).unwrap();let g=reviewed.confirm(&current_store(s),crate::assistant_memory::now()).unwrap().record;assert_eq!(g.schema_version,53);
  let(binding,c)=crate::pet_runtime::context::prepare(&s.f.path.join("contexts"),&g,&s.main,PreparationMode::Dedicated,"derived-service-context").unwrap();drop(c);let g=current_store(s).mutate(&g.id,"integration_spotify",&g.revision,"derived-service-context".into(),Action::BindContext{binding},crate::assistant_memory::now()).unwrap().record;
  let g=current_store(s).mutate(&g.id,"integration_spotify",&g.revision,"derived-service-task".into(),Action::ProposeTask{description:"Own exact deterministic reply".into()},crate::assistant_memory::now()).unwrap().record;
  let g=current_store(s).mutate(&g.id,"integration_spotify",&g.revision,"derived-service-plan".into(),Action::ProposePlan{task_id:g.tasks[0].id.clone(),steps:vec![StepInput{description:"One reviewed reply".into(),postcondition:"Native local receipt only".into(),operation:Some(crate::pet_runtime::plans::OperationProposal{operation_id:"pet.reply".into(),version:2,arguments:json!({"toPetId":r.envelope().origin.pet_id,"source":crate::pet_runtime::messages::ReceivedReference::from_receipt(r).unwrap(),"text":"Own deterministic acknowledgement; no system or music operation","expiresAt":r.envelope().deadline_at})})}]},crate::assistant_memory::now()).unwrap().record;
  let now=crate::assistant_memory::now();let cfg=s.config.clone();let settings=s.settings.clone();let observe:native_peer_plan::Observe=Arc::new(move||Ok((cfg.clone(),settings.clone())));let cap=Budget{deadline_at:r.envelope().deadline_at,max_model_calls:0,max_tool_calls:1,max_output_bytes:4096,max_tokens:None,max_cost_micros:None,payment:Payment::RuntimeOnly};
  let review=GoalReview::prepare_deterministic(&g,crate::pet_runtime::deterministic_runtime_tests::evidence(&g,now),cap,"own-derived-service-admission".into(),nonce().unwrap(),now).unwrap().with_native_peer_plan(&g,&s.f.path.join("goals"),&s.f.path.join("authority"),observe,Some(crate::pet_runtime::planning::Start::WhenAvailable),now).unwrap();let approved=review.approve_with_scopes(&g,crate::pet_runtime::deterministic_runtime_tests::evidence(&g,now),None,Some(Consent::BoundedNativePeerPlan),now).unwrap();assert_eq!(approved.spec().schema_version,11);let cert=s.a.certify(&approved,&g,now).unwrap();let q=current_store(s).enqueue_certified(&cert,now).unwrap().record;
  let(leased,o)=crate::pet_runtime::deterministic_runtime_tests::owned(&s.f,&s.a,&q,&s.main);let(d,status)=std::thread::spawn({let shared=s.clone();let cfg=s.config.clone();let settings=s.settings.clone();move||native_peer_plan::tests::run_with(&shared.f,o,cfg,settings)}).join().unwrap();assert_eq!(status.phase,Phase::Completed,"{status:?}");drop(d);let done=current_store(s).read(&leased.id,"integration_spotify").unwrap();assert_eq!(done.admissions[0].spec.budget.max_model_calls,0);assert!(body(s,&done)["budgetUsage"]["attempts"].as_array().unwrap().iter().all(|a|a["kind"]=="tool"));
 }
 fn revoke(&self){
  let s=&self.base.s;let p=current_store(s).read(&self.base.owner.lease().goal_id,crate::pet_config::pet_id(self.base.provider).unwrap()).unwrap();let b=body(s,&p);let id=b["planningUsage"]["rounds"][1]["peerSources"]["exact"]["observation"]["items"][0]["child"]["goalId"].as_str().unwrap();let path=s.f.path.join("goals").join(format!("{id}.json"));let raw=fs::read(&path).unwrap();fs::write(&path,b"changed original private synthetic source").unwrap();let to=if self.base.provider=="ollama"{"ai_lmstudio"}else{"ai_ollama"};let inbox=s.a.message_inbox(to,None,8,crate::assistant_memory::now()).unwrap();let r=&inbox.items.iter().find(|i|i.receipt.envelope().schema_version==12).unwrap().receipt;assert!(data_review(s,r,"revoked-derived-child-source").is_err());self.denied.store(true,Ordering::Release);fs::write(path,raw).unwrap();let row=&p.admissions[0];s.a.request_stop(&row.spec,row.proof.as_ref().unwrap(),crate::pet_runtime::leases::StopReason::Cancel,crate::assistant_memory::now()).unwrap();crate::pet_runtime::lease_controller::signal_stop(self.base.owner.lease());
 }
}
impl Environment for Env{
 fn capture(&self,o:&Owned)->model::Result<Capture>{self.base.capture(o)}fn configuration(&self)->model::Result<crate::pet_config::Configuration>{self.base.configuration()}fn peer_configuration(&self)->model::Result<(crate::pet_config::Configuration,Settings)>{self.base.peer_configuration()}fn target(&self)->model::Result<Arc<crate::spotify::goal::Target>>{panic!("derived delegation does not grant system/music authority")}
 fn decide(&self,s:Source)->Option<Decision>{self.base.decide(s)}
 fn notify(&self,s:&Status){if s.phase==Phase::WaitingPeers{self.waits.fetch_add(1,Ordering::AcqRel);assert!(self.base.owner.waiting_for_resource());if s.round==2&&self.revoke{self.revoke();}else if s.round==2&&self.service{self.service();}else{self.base.child();}}else{self.base.notify(s);}}
}
fn exercise(provider:&'static str,models:u16,choice:bool,service:bool,revoke:bool){
 let s=Arc::new(Setup::new());let deadline=crate::assistant_memory::now()+90_000;let g=s.f.goal_named_criteria(provider,"two-derived-funded-branches",vec!["Independent proof of the actual outcome".into()]);let to=if provider=="ollama"{"ai_lmstudio"}else{"ai_ollama"};let branch=|target:&str,text:&str,models:u16,criterion:&str|json!({"kind":"plan","description":"One independently admitted branch","steps":[{"description":"One bounded delegation","postcondition":"Local receipt is not actual success","operation":{"operationId":"pet.delegate","version":1,"arguments":{"toPetId":target,"subgoal":text,"criteria":[criterion],"expiresAt":deadline,"allowance":{"modelCalls":models,"toolCalls":1,"outputBytes":16384},"maxDepth":2}}}]});let first=branch(to,"First finite own task",1,"Independent criterion");let second=branch(if service{"integration_spotify"}else{to},"Derived independently reviewed task",if service{0}else{1},if service{NATIVE_MESSAGE_CRITERION}else{"Independent derived criterion"});
 let meta=if provider=="lmstudio"{lm_metadata()}else{metadata()};let(mut server,http)=http_fixture(vec![("application/json",meta.to_string()),("text/event-stream",stream(&first.to_string(),true)),("application/json",meta.to_string()),("text/event-stream",stream(&second.to_string(),true))],|_|{});server.id=provider;
 let(_,o)=parent_with_budget(&s,&g,&server,deadline,models,4);let env=Arc::new(Env{base:IterationEnv{s:s.clone(),provider,url:server.url.clone(),owner:o.clone(),approve_data:true,stop_wait:false,approve_derived:choice,busy_delivery:false,delivery_blocked:AtomicBool::new(false),store_lock:Mutex::new(None),child_started:AtomicBool::new(false),decisions:AtomicUsize::new(0),waits:AtomicUsize::new(0),child_requests:Mutex::new(vec![])},waits:AtomicUsize::new(0),service,revoke,denied:AtomicBool::new(false)});let driver=Driver::new(o.clone(),Arc::new(current_store(&s)),env.clone()).unwrap();let result=run(driver.run());assert_eq!(http.join().unwrap().len(),4);let root=current_store(&s).read(&g.id,&g.spec.owner.pet_id).unwrap();let b=body(&s,&root);
 if models==3&&!service{assert_eq!(result.unwrap().phase,Phase::Limited);assert_eq!(o.workers(),0);assert_eq!(env.base.decisions.load(Ordering::Acquire),2);assert_eq!(b["messages"]["entries"].as_array().unwrap().len(),1);assert_eq!(b["delegationReservations"].as_array().unwrap().len(),1);return;}
 let status=result.unwrap_or_else(|e|panic!("{e:?}; {:?}",driver.status()));assert_eq!(status.phase,if !choice{Phase::Declined}else if revoke{Phase::Stopped}else{Phase::AwaitingVerification},"{status:?}");assert_eq!(env.base.decisions.load(Ordering::Acquire),3);assert_eq!(env.waits.load(Ordering::Acquire),if choice{2}else{1});assert!(root.completion.is_none());assert_eq!(b["messages"]["entries"].as_array().unwrap().len(),if choice{2}else{1});assert_eq!(o.workers(),0);assert_eq!(b["budgetUsage"]["attempts"].as_array().unwrap().iter().filter(|a|a["kind"]=="model").count(),2);
 if !choice{return;}assert_eq!(b["schemaVersion"],43);assert_eq!(b["messages"]["schemaVersion"],12);assert_eq!(b["delegationReservations"].as_array().unwrap().len(),2);assert_eq!(b["messages"]["entries"][1]["scope"]["envelope"]["schemaVersion"],12);assert_eq!(b["messages"]["entries"][1]["scope"]["envelope"]["plannedData"]["schemaVersion"],2);assert!(!b["messages"]["entries"][1]["scope"]["envelope"]["providerUseAuthorized"].as_bool().unwrap());if revoke{assert!(env.denied.load(Ordering::Acquire));return;}
 assert_eq!(b["resourceUsage"]["entries"].as_array().unwrap().len(),5);let view=s.a.delegation_view(&root,&root.admissions[0].spec.decision_id,crate::assistant_memory::now()).unwrap();assert_eq!(view.held.unwrap().model_calls,if service{1}else{2});let remaining=view.remaining.unwrap();assert_eq!(remaining.model_calls,models-2-if service{1}else{2});assert_eq!(remaining.tool_calls,0);let reservation=&view.reservations[1];let binding=reservation.binding().unwrap();let child=current_store(&s).read(&binding.goal_id,&binding.pet_id).unwrap();assert_eq!(child.schema_version,53);assert_eq!(child.spec.received_from.as_ref().unwrap().body.schema_version,7);assert_eq!(child.admissions[0].spec.schema_version,if service{11}else{23});assert!(binding.matches(&child.admissions[0].spec));if !service{assert!(child.completion.is_none());assert_eq!(child.execution_context.as_ref().unwrap().schema_version,9);assert_eq!(child.admissions[0].spec.memory_data.as_ref().unwrap().schema_version,8);assert_eq!(body(&s,&child)["budgetUsage"]["attempts"].as_array().unwrap().len(),1);}
 let mut down=child.clone();down.schema_version=52;assert!(down.validate().is_err());
}
#[test]fn derived_funded_second_branch_uses_own_f2_same_total_budget_and_common_driver_on_both_local_engines(){for p in["ollama","lmstudio"]{exercise(p,4,true,false,false);}}
#[test]fn derived_service_branch_uses_own_deterministic_admission_without_loading_a_model_or_system_authority(){exercise("ollama",3,true,true,false);}
#[test]fn derived_branch_refusal_or_insufficient_total_balance_creates_no_extra_reservation(){exercise("ollama",4,false,false,false);exercise("ollama",3,true,false,false);}
#[test]fn original_source_revocation_after_derived_dispatch_blocks_new_child_admission_and_parent_stop_never_replays(){exercise("ollama",4,true,false,true);}
